<script setup lang="ts">
import {computed,ref} from 'vue';
import type {TodayFacts,TodayRawTodo} from '../../shared/today-facts.mjs';
import {useTodayAdvice,type TodayReason} from '../stores/today';
import {nativeBridgeAvailable} from '../lib/host-capabilities.ts';
import SkButton from './ui/SkButton.vue';
import SkCheckbox from './ui/SkCheckbox.vue';
const today=useTodayAdvice(),dialog=ref<HTMLDialogElement>(),consent=ref(false);let lastFocus:HTMLElement|null=null;
const nativeAvailable=nativeBridgeAvailable();
const success=computed(()=>today.data?.lastSuccess),facts=computed(()=>success.value?.snapshot.todayFacts),labels:Record<string,string>={open:'开放',completed:'已完成',deleted:'已删除',action:'待我处理',followup:'待我跟进',low:'低',medium:'中',high:'高',manual:'手工录入',signed_ai:'已签收'};
const timestamp=(value:number,timeZone=facts.value?.timeZone||today.data?.facts.timeZone||'UTC')=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'short',timeStyle:'short',timeZone}).format(new Date(value));
const factGroups=computed(()=>{const groups:{key:string;label:string;facts:TodayFacts}[]=[];if(today.data)groups.push({key:'current',label:today.currentVerified?'当前完整事实':'最近读取的事实（当前性未确认）',facts:today.data.facts});if(facts.value)groups.push({key:'snapshot',label:'本次完整事项快照',facts:facts.value});return groups;});
function snapshotPoint(point:NonNullable<TodayRawTodo['data']['due']>,zone:string){return point.precision==='day'?new Intl.DateTimeFormat('zh-CN',{dateStyle:'short',timeZone:point.timeZone}).format(new Date(point.atMs))+'（仅日期）':timestamp(point.atMs,zone);}
function reason(item:TodayReason){const labels:Record<string,string>={due_today:'今日交付',followup_today:'今日跟进',upcoming_due:'后续有交付日期',undated:'交付与跟进日期均未定',open_action:'本人待处理事项',open_followup:'本人待跟进事项',overdue:'本快照中交付已逾期'};if(item.code==='earlier_due'){const other=facts.value?.todos.find(todo=>todo.id===item.relatedTodoId);return `交付日期早于“${other?.title||'快照事项'}”`;}return labels[item.code]||'请核对原快照';}
async function openUpgrade(){lastFocus=document.activeElement as HTMLElement;consent.value=false;try{await today.loadStorage();dialog.value?.showModal();}catch{}}
function closeUpgrade(){if(today.upgrading)return;dialog.value?.close();lastFocus?.focus();}
async function upgrade(){try{await today.upgrade(consent.value);closeUpgrade();}catch{}}
async function generate(){if((today.data?.storageVersion||0)<5){await openUpgrade();return;}try{await today.start();}catch{}}
</script>
<template>
<section class="today-advice" aria-labelledby="today-advice-title"><h3 id="today-advice-title">今日建议</h3><p class="muted">只读排序与依据，截止、负责人和状态由你决定。</p>
<p v-if="today.error" class="danger" role="alert">{{ today.error }}</p><p v-if="today.upgradeError" class="danger" role="alert">{{ today.upgradeError }}</p>
<p v-if="today.data" class="muted">{{ today.currentVerified?'':'最近读取：' }}{{ today.data.facts.date }} · {{ today.data.facts.timeZone }}<br>有效 {{ today.data.facts.counts.total }} · 开放 {{ today.data.facts.counts.open }} · 已完成 {{ today.data.facts.counts.completed }}<br>今日交付 {{ today.data.facts.counts.dueToday }} · 今日跟进 {{ today.data.facts.counts.followupToday }}<br>逾期 {{ today.data.facts.counts.overdue }} · 未定期 {{ today.data.facts.counts.undated }} · 保留删除 {{ today.data.facts.counts.deleted }}</p>
<div class="advice-actions"><SkButton kind="entry" :disabled="!nativeAvailable||!today.data||!today.data.facts.counts.open||today.starting||today.running||today.upgrading||today.upgradeUnknown" :loading="today.starting" @click="generate">{{ (today.data?.storageVersion||0)<5?'启用今日建议':'刷新建议' }}</SkButton><SkButton v-if="today.running" :loading="today.cancelling" @click="today.cancel().catch(()=>{})">取消生成</SkButton><SkButton kind="quiet" :disabled="!nativeAvailable||today.loading||today.upgrading" @click="today.load().catch(()=>{})">重新核对</SkButton></div>
<p v-if="!nativeAvailable" class="muted">未接通：浏览器模式不生成今日建议，手工事项不受影响。</p>
<p v-if="today.running" class="muted" role="status">{{ today.data?.latest?.snapshot.todayPreparation?'正在核对事项事实，可随时取消。':'正在生成，当前事实与上次成功结果继续保留。' }}</p><p v-else-if="today.data?.latest&&today.data.latest.status!=='succeeded'" class="muted" role="status">最近一次：{{ {failed:'生成失败',cancelled:'已取消',interrupted:'运行中断',running:'生成中'}[today.data.latest.status] }}{{ today.data.latest.errorCode?`（${today.data.latest.errorCode}）`:'' }}；保留事实版及上次成功结果。</p>
<p v-if="today.data&&!today.data.facts.counts.open" class="muted">当前没有开放事项，先保留事实版。</p>
<template v-if="success&&facts"><h4>{{ today.data?.latest?.id===success.id?'最近成功建议':'上次成功建议' }}</h4><p class="muted">生成于 {{ timestamp(success.finishedAtMs||success.createdAtMs) }}<br>快照：{{ facts.date }} · {{ facts.timeZone }}</p><p v-if="today.data?.lastSuccessStale||today.loading||!today.currentVerified" class="danger" role="status">{{ today.loading?'正在核对当前性，暂不视为当前建议。':!today.currentVerified?'当前性暂未确认，请重新核对。以下保留上次成功快照。':'事实已变化，请刷新建议。以下保留原快照。' }}</p><p v-else class="muted">已与当前事实核对。</p><ol v-if="success.result?.ranking.length"><li v-for="item in success.result.ranking" :key="item.todoId"><strong>{{ facts.todos.find(todo=>todo.id===item.todoId)?.title }}</strong><p class="muted">{{ item.reasons.map(reason).join('；') }}</p></li></ol><p v-else class="muted">本次未给出排序建议，完整事实仍在。</p>
</template><p v-else class="muted">尚无成功建议；已保存的本地事实继续显示。</p>
<details v-for="group in factGroups" :key="group.key"><summary>{{ group.label }}（{{ group.facts.rawTodos.length }} 项）</summary><ul><li v-for="todo in group.facts.rawTodos" :key="todo.id"><strong>{{ todo.data.title }}</strong><p class="muted">{{ labels[todo.data.kind] }} · {{ todo.data.owner }} · {{ labels[todo.status] }} · 优先级{{ labels[todo.data.priority] }} · v{{ todo.version }}<br>交付：{{ todo.data.due?`${snapshotPoint(todo.data.due,group.facts.timeZone)}；原表达：${todo.data.due.localText}（${todo.data.due.timeZone}）`:'未定' }}<br>跟进：{{ todo.data.followup?`${snapshotPoint(todo.data.followup,group.facts.timeZone)}；原表达：${todo.data.followup.localText}（${todo.data.followup.timeZone}）`:'未定' }}<br>{{ labels[todo.source] }}{{ todo.data.tags.length?` · ${todo.data.tags.join('、')}`:'' }}<br>创建 {{ timestamp(todo.createdAtMs,group.facts.timeZone) }} · 更新 {{ timestamp(todo.updatedAtMs,group.facts.timeZone) }}<template v-if="todo.completedAtMs"><br>完成 {{ timestamp(todo.completedAtMs,group.facts.timeZone) }}</template><template v-if="todo.deletedAtMs"><br>删除 {{ timestamp(todo.deletedAtMs,group.facts.timeZone) }}</template></p></li></ul></details>
<p v-if="today.backup" class="muted">已确认备份：{{ today.backup }}</p>
<dialog ref="dialog" class="advice-dialog" aria-labelledby="today-upgrade-title" @cancel.prevent="closeUpgrade"><h2 id="today-upgrade-title">启用今日建议存储</h2><p v-if="today.storage">将当前本地数据库从 v{{ today.storage.version }} 升级到 v5。升级前保存一致性备份；不会连接 MCP 服务。</p><p v-else>当前目录与版本需要重新读取并核对，本次未执行升级。</p><p class="muted path">{{ today.storage?.root }}</p><p v-if="today.storage" class="muted path">一致性备份目录：{{ today.storage.root }}/backups/<br>备份文件以 before-schema-5- 开头（如 before-schema-5-123-456.sqlite）；升级完成后显示确切路径。</p><p>升级后旧版本无法打开此根。保留当前根与备份；恢复需使用兼容应用，不能直接降版写入当前数据库。</p><SkCheckbox v-model="consent" :disabled="today.upgrading">我已核对当前工作目录、备份及旧版本兼容说明</SkCheckbox><p v-if="today.upgradeError" class="danger" role="alert">{{ today.upgradeError }}</p><div class="advice-actions"><SkButton :disabled="today.upgrading" @click="closeUpgrade">取消</SkButton><SkButton kind="quiet" :disabled="today.upgrading||today.upgradeUnknown" @click="consent=false;today.loadStorage().catch(()=>{})">重新读取</SkButton><SkButton kind="commit" :disabled="!consent||!today.storage?.confirmationToken||today.upgradeUnknown" :loading="today.upgrading" @click="upgrade">备份并升级</SkButton></div></dialog>
</section>
</template>
<style scoped>
.today-advice{margin-top:24px;padding-top:20px;border-top:1px solid var(--line);overflow-wrap:anywhere}.today-advice h3,.today-advice h4{margin-bottom:10px}.today-advice p{font-size:12px;line-height:1.8}.advice-actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.today-advice ol,.today-advice ul{padding-left:20px;font-size:12px}.today-advice li{margin:12px 0}.today-advice summary{cursor:pointer;font-size:12px}.advice-dialog{position:fixed;inset:0;margin:auto;max-width:540px;width:calc(100% - 40px);max-height:calc(100vh - 40px);overflow:auto;border:1px solid var(--line);border-radius:var(--radius);background:var(--surface);color:var(--ink);padding:24px}.advice-dialog::backdrop{background:var(--ink);opacity:.25}.advice-dialog .path{overflow-wrap:anywhere}
</style>
